            dr = pos + 1 - top
            trace = bottom + dr + 1
        else:
            return out
        for r, c, v in points:
            out[r][c] = background
        for r, c, v in points:
            out[r + dr][c] = v
        if 0 <= trace < h:
            out[trace] = [8] * w
    else:
        left = min(c for r, c, v in points)
